def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.35)

    prev_bids = []
    prev_high_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= 500:
            rich_count += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(bid)
                if bid >= 110:
                    prev_high_bids.append(bid)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = 1.0 - max(0.0, min(1.0, supply_ratio))

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    if no_water_days >= 2:
        urgency += 1.0
    elif no_water_days >= 1:
        urgency += 0.45
    urgency += scarcity * 0.7
    if day >= 8:
        urgency += 0.15

    if hp <= 2 or no_water_days >= 2:
        target = max(118.0, highest_prev + 2.0, DAILY_SALARY * 1.7)
    elif hp <= 4 or no_water_days >= 1:
        target = max(96.0, avg_prev * 0.9, highest_prev - 4.0)
    else:
        if supply >= 22:
            target = 48.0
        elif supply >= 19:
            target = 62.0
        else:
            target = 78.0

        if highest_prev >= 130 and urgency < 0.8:
            target = min(target, 60.0)
        elif highest_prev >= 115 and scarcity > 0.5:
            target = max(target, 82.0)

    if desperate_count >= 2 and scarcity > 0.4:
        target += 8.0
    if rich_count >= 2 and highest_prev >= 115:
        target += 5.0

    if budget < 140:
        target = min(target, budget * 0.72)
    elif budget < 250:
        target = min(target, budget * 0.6)

    target = max(0.0, min(float(target), float(budget)))
    return target

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(my_status['budget'], DAILY_SALARY * 0.4))

    # Extract yesterday bids and outcomes
    prev_bids = []
    prev_high_pressure = 0.0
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b = float(b)
            except Exception:
                continue
            prev_bids.append(b)
            if b > prev_high_pressure:
                prev_high_pressure = b

    # Budget and HP pressure
    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Determine aggressiveness target based on yesterday's max bid (proxy for how costly water is)
    # If others were bidding extremely high, we avoid matching them (they may be budget-constrained).
    # If yesterday pressure was moderate, we bid to win.
    if prev_bids:
        highest_prev_bid = max(prev_bids)
    else:
        highest_prev_bid = 0.0

    # Supply-based baseline: lower supply -> higher chance others fight; but we still cap to avoid draining.
    # Normalize supply in [MIN_SUPPLY, MAX_SUPPLY]
    if MAX_SUPPLY == MIN_SUPPLY:
        supply_norm = 0.5
    else:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        if supply_norm < 0.0:
            supply_norm = 0.0
        if supply_norm > 1.0:
            supply_norm = 1.0

    # Base bid: mid-tier to beat typical cautious bids but undercut extreme bidders
    # When supply is low (norm small), bid higher.
    base = DAILY_SALARY * (0.48 + (0.5 - supply_norm) * 0.35)  # roughly 0.48..0.655 of salary

    # React to our own survival risk
    if my_hp <= 2.0 or no_water_days >= 2:
        base = DAILY_SALARY * 0.85
    elif my_hp <= 4.0 or no_water_days >= 1:
        base = DAILY_SALARY * 0.65

    # Undercut extreme yesterday max bids: if others went very high, don't chase; bid just below a threshold.
    # Use a soft cap relative to highest_prev_bid.
    if highest_prev_bid >= DAILY_SALARY * 1.2:
        # Others likely overcommitting; bid lower than their peak by a margin
        target = min(base, highest_prev_bid * 0.78)
    elif highest_prev_bid >= DAILY_SALARY * 0.9:
        # Moderate-high pressure: bid around base but slightly higher
        target = max(base, highest_prev_bid * 0.62)
    else:
        target = base

    # Ensure we never exceed budget
    bid = min(my_budget, float(target))

    # If budget is tiny, still bid something proportional to avoid guaranteed loss when low supply
    if my_budget <= DAILY_SALARY * 0.2:
        bid = min(my_budget, DAILY_SALARY * 0.15 + my_budget * 0.85)

    # Final clamp
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Get yesterday's highest bid among alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if day_context['day'] == 1 or not yesterday_bids:
        # First day or no trace: bid based on HP
        if my_status['hp'] <= 2:
            return min(my_status['budget'], DAILY_SALARY * 0.9)
        elif my_status['hp'] <= 5:
            return min(my_status['budget'], DAILY_SALARY * 0.7)
        else:
            return min(my_status['budget'], DAILY_SALARY * 0.5)

    highest_prev_bid = max(yesterday_bids)

    # If someone bid very high yesterday, they might repeat; conserve if possible
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if my_status['hp'] > 3:
            return min(my_status['budget'], DAILY_SALARY * 0.3)
        else:
            # Must secure water
            return min(my_status['budget'], DAILY_SALARY * 0.95)
    else:
        # Moderate pressure: match or slightly beat yesterday's high
        target = max(DAILY_SALARY * 0.5, highest_prev_bid + 1.0)
        return min(my_status['budget'], target)
